import { addSection7Visual } from "./course-v3-section7-visuals.mjs";
const ids = (r, ...ns) => ns.map((n) => `S7.${String(r).padStart(2, "0")}.A${String(n).padStart(2, "0")}`);
const objective = (r, n, text) => [ids(r, n)[0], text];
const table = (title, headers, rows) => ({ type: "table", title, headers, rows, preserveText: true });
const flow = (title, steps) => ({ type: "flow", title, steps, preserveText: true });
const worked = (title, steps) => ({ type: "worked-example", title, steps });
const unit = (key, heading, objectiveIds, explanation, materials, misconception, prompt, answer) => ({
  unitKey: `S7-${key}`, syllabusId: objectiveIds[0].replace(/\.A\d+$/, ""), heading, objectiveIds,
  explanation, materials: materials.map((m) => ({ ...m, objectiveIds })), misconceptions: [misconception],
  useAuthoredVisual: true, checkpoint: { prompt, answer },
});
const question = (id, prompt, objectiveIds, answerPoints, commonError) => ({
  id, prompt, objectiveIds, answerPoints, commonError, marks: answerPoints.length, type: "Application", authored: true,
});
const q = (lesson, n, ...args) => question(`S7-L0${lesson}-Q${n}`, ...args);
const e = (lesson, n, ...args) => question(`S7-L0${lesson}-EXAM-${n}`, ...args);

const professionalEthics = {
  subtitle: "Explain why computing professionals need ethical principles, apply their duties, and recognise how professional bodies support responsible practice.",
  guidingQuestion: "What should a computing professional do when a requested action could harm users?",
  diagnostic: { prompt: "An employee can read a customer record using a valid account. Does access permission alone justify every use of it?", answer: "No. Access permission does not establish that a use is appropriate; consider the purpose, affected people and professional responsibilities." },
  objectives: [
    objective(1, 1, "Explain the need for and purpose of ethics as a computing professional."),
    objective(1, 2, "Apply professional duties and distinguish ethical judgement from legal compliance."),
    objective(2, 1, "Identify BCS and IEEE as professional bodies."),
    objective(2, 2, "Explain why joining a professional ethical body supports professional practice."),
  ],
  units: [
    unit("PURPOSE", "Why computing professionals need ethics", ids(1, 1), [
      "Ethics concerns principles about right and wrong conduct. A computing professional makes decisions that can affect other people's safety, privacy, opportunities and resources. Users may lack the technical knowledge or access needed to detect an unsafe system or challenge its design, so technical power brings responsibilities.",
      "Professional ethics helps guide decisions when interests conflict or a rule does not settle what should be done. Its purposes include protecting the public interest, promoting honest and competent work, maintaining trust and making professionals accountable for foreseeable effects of their decisions.",
    ], [table("From technical power to responsibility", ["Professional can...", "Others depend on...", "Ethical concern"], [["Design a medical warning", "Reliable information about danger", "Patient safety"], ["Access personnel records", "Appropriate use of private details", "Confidentiality"], ["Report a software test result", "An honest basis for release", "Integrity of professional advice"]])],
    "A technically possible action is not automatically an ethical action.",
    "Why is ethics relevant even when a customer cannot detect an unsafe design?", "The professional's responsibility to avoid foreseeable harm does not depend on whether the customer can discover the problem."),
    unit("DUTIES", "Professional duties and legal compliance", ids(1, 2), [
      "A professional should work within their competence, report limitations honestly, protect confidential information and consider effects on the public. Conflicting interests should be disclosed so that advice can be evaluated fairly. For example, a paid relationship with a supplier can influence a recommendation even when that recommendation is technically possible.",
      "Law sets enforceable requirements; ethical judgement also considers what is responsible in the particular circumstances. An employer's instruction or the absence of an explicit legal prohibition does not remove a professional's duty to consider harm. A defensible response records the concern, seeks appropriate guidance and proposes an action that addresses it.",
    ], [table("Recognise the professional duty", ["Situation", "Duty", "Appropriate response"], [["Asked to certify an unfamiliar system", "Competence", "Seek qualified assistance"], ["Known limitations omitted from a report", "Honesty", "Disclose the limitations"], ["Supplier offers a personal reward", "Integrity", "Declare the conflict of interest"]]), worked("An untested warning system", [["Request", "A developer is asked to describe a building's new fire-warning interface as fully tested, although the warning display has failed one test."], ["Duty", "Occupants depend on that warning. An honest report must include the failed test and its safety implications."], ["Response", "Record the fault, notify the responsible safety lead and recommend correcting and retesting the display before relying on it."], ["Reason", "A manager's wish to meet a deadline does not justify concealing evidence on which a safety decision depends."]])],
    "Ethical reasoning requires an explanation of the duty and its consequences, not simply the label 'legal' or 'illegal'.",
    "A manager requests an inaccurate test report. Who remains responsible for writing it?", "The professional remains accountable for their own report and should raise the concern rather than treat the instruction as sufficient justification."),
    unit("BODIES", "BCS, IEEE and the value of membership", ids(2, 1, 2), [
      "BCS is the British Computer Society. IEEE is the Institute of Electrical and Electronics Engineers. These professional bodies provide codes of conduct or ethics that express standards expected of members. A shared code gives a practitioner a reference when explaining a professional concern to an employer or client.",
      "Joining can provide continuing professional development, technical information and contact with experienced peers. These help members maintain competence and obtain guidance when a problem exceeds their experience. Membership also brings expectations of conduct and accountability through the body's professional processes, supporting public confidence in the profession.",
      "A code supports judgement but cannot guarantee that every member acts ethically. Membership does not replace the law, remove personal responsibility or automatically certify every product a member develops.",
    ], [table("Membership support and its purpose", ["Support", "Practical value"], [["Professional code", "A recognised basis for raising a concern"], ["Continuing development", "Keep knowledge and skills current"], ["Peer community and guidance", "Discuss difficult professional situations"], ["Conduct procedures", "Provide a route for accountability"]])],
    "Naming a professional body does not explain why joining it matters.",
    "Does a developer's IEEE membership prove that their application is safe?", "No. Membership supports professional standards; the application's safety still needs appropriate design, testing and review."),
  ],
  practice: [
    q(1, 1, "Explain two reasons why professional ethics is needed when designing a system that stores private patient records.", ids(1, 1), ["Patients depend on specialists to protect information they cannot directly control, so professional duties help prevent misuse of that access.", "Rules may not resolve every proposed use of the records, so ethical principles help the designer judge effects on patients."], "Develop each reason using the records context."),
    q(1, 2, "State two purposes of ethics in the computing profession.", ids(1, 1), ["Protect the public interest when computing decisions affect people.", "Promote trustworthy, accountable professional conduct."], "Two restatements of 'doing the right thing' are not two distinct purposes."),
    q(1, 3, "An employee is asked to sign off a system outside their expertise. Explain why obeying the instruction alone is insufficient and suggest a responsible action.", ids(1, 2), ["Approval without the necessary competence could give others unjustified confidence in the system.", "The employee should disclose the limit of their expertise and seek a suitably qualified review."], "Link the action to the competence problem."),
    q(1, 4, "Identify the professional bodies abbreviated BCS and IEEE.", ids(2, 1), ["BCS: British Computer Society.", "IEEE: Institute of Electrical and Electronics Engineers."], "Give the organisation names rather than examples of software companies."),
    q(1, 5, "Explain two ways joining a professional body could help a programmer keep their skills current and respond to pressure to hide a fault.", ids(2, 2), ["Continuing professional development can help the programmer learn current techniques and recognise limits in their knowledge.", "A professional code gives the programmer recognised standards with which to explain why the fault should be reported."], "Connect each membership benefit to one of the two stated needs."),
  ],
  authoredExamQuestions: [
    e(1, 1, "A contractor discovers that a bridge-monitoring program sometimes suppresses a danger alert. The customer cannot inspect the source. Explain why professional ethics is necessary here and give two purposes it serves.", ids(1, 1), ["The contractor has specialist knowledge of a risk that the customer cannot independently assess, creating a responsibility to disclose it.", "Ethical standards protect people who might assume there is no danger when the warning is suppressed.", "They make the contractor answerable for honest advice about whether the monitoring system can be trusted."], "Apply the explanation to the hidden alert fault; unrelated benefits of automation do not answer this question."),
    e(1, 2, "A consultant recommends a supplier while secretly receiving a payment from that supplier. The consultant says, 'My employer has not forbidden this, so it must be ethical.' Explain why the reasoning is insufficient and suggest a responsible response.", ids(1, 2), ["An absent employer rule does not establish that the advice is independent or fair to the client.", "The undisclosed payment creates a conflict between the consultant's personal interest and the client's needs.", "The consultant should disclose the payment and arrange an impartial evaluation of the suppliers."], "Explain the conflict rather than assuming that every recommendation involving payment is technically wrong."),
    e(1, 3, "Identify BCS and IEEE. A new engineer joins one of these bodies to obtain professional guidance. Explain two benefits of membership and one reason it cannot guarantee ethical behaviour.", ids(2, 1, 2), ["BCS means British Computer Society, a professional computing body.", "IEEE means Institute of Electrical and Electronics Engineers, a professional engineering body.", "Its published conduct standards help the engineer decide how to raise a concern consistently with professional duties.", "Its learning activities and peer network help the engineer develop competence and seek informed advice.", "The engineer still chooses how to act and can disregard the standards despite being a member."], "Explain the effects of membership rather than crediting membership as proof of good conduct."),
  ],
  summary: [["Purpose", "Professional decisions should protect affected people and sustain trust in specialist work."], ["Duties", "Be competent, honest and accountable; disclose conflicts and protect confidential information."], ["Judgement", "An instruction or a gap in the rules does not settle whether an action is responsible."], ["Membership", "BCS and IEEE offer standards, development and guidance while members retain responsibility for their actions."]],
};

const ethicalDecisions = {
  subtitle: "Identify stakeholders, compare the consequences of two courses of action and justify a response to a specific ethical problem.",
  guidingQuestion: "How can an ethical judgement show exactly who is affected and why?",
  diagnostic: { prompt: "A response says only 'The programmer is unethical.' What evidence is missing?", answer: "It must identify the action, the relevant duty and an effect on a named stakeholder." },
  objectives: [objective(3, 1, "Identify stakeholders and professional responsibilities in a given situation."), objective(3, 2, "Explain consequences of acting ethically and unethically for affected stakeholders."), objective(3, 3, "Justify an ethical action using evidence, alternatives and safeguards.")],
  units: [
    unit("STAKEHOLDERS", "Identify the decision and the people affected", ids(3, 1), [
      "Begin with the actual decision: what is someone proposing to collect, disclose, change or conceal? Identify direct stakeholders, such as users and employees, and others affected indirectly, such as families or the wider public. Different groups may have different interests in the same system.",
      "Connect each stakeholder to a relevant responsibility. A school handling location data has duties towards pupils' privacy as well as safety. Naming 'society' without explaining a connection is too vague to support a judgement. Benefits and harms are parallel possibilities to investigate; one is not automatically the cause of the other.",
    ], [table("School trip location sharing", ["Stakeholder", "Possible benefit", "Possible harm or concern"], [["Pupils", "Faster assistance if separated", "Movement history exposed unnecessarily"], ["Trip leaders", "Locate a missing pupil", "Responsibility for inappropriate access"], ["Parents", "Reassurance during the trip", "Details reused without a clear purpose"]])],
    "A possible benefit does not automatically cause the possible harm; analyse each effect separately.",
    "Why is a parent a stakeholder even if they never operate the tracking system?", "The system's decisions can affect their child's safety and privacy, so the parent has an interest in its use."),
    unit("CONSEQUENCES", "Compare ethical and unethical actions", ids(3, 2), [
      "Explain consequences through a cause-and-effect link: the action changes what happens to a stakeholder. For example, disclosing a known defect allows a client to avoid relying on unsafe output; concealing it can lead the client to make a harmful decision with misplaced confidence.",
      "Consider both courses of action. Acting ethically can have an immediate cost, such as delay or extra testing, while preserving safety and trust. Acting unethically may produce a short-term advantage but can cause harm, complaints, loss of confidence or professional consequences. State consequences supported by the situation rather than assuming that every outcome is certain.",
    ], [table("Two responses to a reported defect", ["Action", "Short-term effect", "Further consequence"], [["Report and investigate", "Release may be delayed", "Client can make an informed decision"], ["Hide and release", "Deadline appears to be met", "Users may rely on incorrect results"]]), worked("A travel application's accessibility error", [["Situation", "A developer finds that a route labelled wheelchair-accessible includes steps. The manager wants to publish the route unchanged to meet a launch date."], ["Ethical course", "Correct or withdraw the label and tell the travel operator about the uncertainty. Launch may be delayed, but wheelchair users can avoid an unsuitable route."], ["Unethical course", "Keep the label and hide the report. A user may reach an inaccessible location and need assistance; the operator may receive complaints and lose trust."], ["Comparison", "The deadline benefit does not remove the duty to provide reliable accessibility information. The correction addresses a foreseeable consequence for a specific group."]])],
    "Simply writing 'good reputation' or 'bad reputation' leaves out the action and why it changes trust.",
    "Can an ethical response still cost the organisation money?", "Yes. Correcting a problem may cost money or delay a release while preventing harm and supporting justified trust."),
    unit("JUDGEMENT", "Justify a proportionate response", ids(3, 3), [
      "Use evidence to weigh the stated purpose against the effects on people. Compare a realistic alternative that could meet the purpose with less intrusion or risk. Proportionality means the action should be appropriate to the need and no more intrusive or harmful than necessary to achieve it.",
      "A conclusion should identify an action and explain why it is justified. Relevant safeguards might include limiting collection and retention, restricting access, correcting inaccurate information or providing a way to challenge a decision. A safeguard needs a mechanism linked to the particular risk, and it may reduce rather than eliminate that risk.",
    ], [flow("Build a supported judgement", [["Decision", "Identify the proposed action and legitimate purpose."], ["Evidence", "Connect benefits, harms and duties to affected people."], ["Alternative", "Test whether a less intrusive option meets the purpose."], ["Conclusion", "Choose an action with relevant conditions and remaining limits."]]), worked("Continuous tracking for attendance", [["Proposal", "A college wants students' phones to report location all day and night, but its stated aim is to confirm arrival at lessons."], ["Alternative", "A check-in at the classroom can record attendance without keeping an off-site movement history."], ["Judgement", "Use classroom check-in with restricted access and a short retention period. Continuous overnight tracking is unnecessary for this attendance purpose."], ["Remaining issue", "Check-in errors still need a correction process so a failed scan does not unfairly mark a student absent."]])],
    "A balanced response need not treat all choices as equally acceptable or end with an unsupported compromise.",
    "How does a short retention period address a privacy concern?", "Deleting records after their stated purpose ends reduces the amount of historical information available for misuse."),
  ],
  practice: [
    q(2, 1, "A town publishes named residents' complaints on an open website to show how quickly repairs are handled. Identify two stakeholders and explain one concern for each.", ids(3, 1), ["Residents who complained may have private contact or complaint details exposed.", "Town staff need to report performance without losing residents' trust through unnecessary disclosure."], "Explain how each group is affected rather than listing unrelated organisations."),
    q(2, 2, "A developer knows that a delivery app sends drivers to a closed bridge. Explain one consequence for drivers of reporting the error and one of concealing it.", ids(3, 2), ["Reporting the defect allows the route to be corrected or warned against, helping drivers avoid wasted or unsafe journeys.", "Concealing it leaves drivers relying on a route that cannot be completed, causing delay and possible safety risks."], "Use both actions and make the consequence specific to drivers."),
    q(2, 3, "A company postpones a booking-system launch to correct a fault that loses reservations. Explain one short-term cost and one longer-term benefit of this decision.", ids(3, 2), ["Postponement may delay booking revenue or require extra development expenditure.", "Fixing the fault reduces lost reservations and helps retain customers' confidence in future bookings."], "Ethical behaviour does not imply an absence of immediate costs."),
    q(2, 4, "A sports club needs emergency contacts for one weekend trip but proposes keeping them indefinitely for advertising. Justify a more appropriate use of the data and suggest two safeguards.", ids(3, 3), ["Limit use to the trip's emergency purpose because advertising is a separate use the stated need does not justify.", "Restrict access to staff responsible for emergencies.", "Delete the list after the trip and any justified follow-up period instead of retaining it indefinitely."], "Each safeguard must address access, purpose or retention in this scenario."),
    q(2, 5, "A response to an attendance proposal says, 'Tracking everyone is good because it is efficient.' Explain two weaknesses in this reasoning and suggest an alternative to continuous location tracking.", ids(3, 1, 3), ["It does not identify whose efficiency improves or how the claimed improvement occurs.", "It ignores students' privacy and whether continuous monitoring is necessary for attendance.", "Recording arrival at the classroom can meet the attendance need with less collection of movement data."], "Critique the supplied reasoning rather than inventing a different response."),
  ],
  authoredExamQuestions: [
    e(2, 1, "A school plans to display named pupils' medical conditions on a public dashboard to help trip organisers. Identify two affected groups and explain one professional responsibility towards each.", ids(3, 1), ["Pupils whose conditions are listed are affected because public disclosure can expose sensitive personal details.", "The school should keep those details available only to people who need them for the trip.", "Trip organisers are affected because they rely on medical information to respond safely.", "The school should supply organisers with accurate, relevant information through an appropriate restricted channel."], "Connect each responsibility to a named group and the proposed disclosure."),
    e(2, 2, "An accountant reports that a payroll program underpays overtime. Its developer can report the fault immediately or hide it until after a bonus is paid for meeting the release date. Explain a consequence for employees and a consequence for the employer for each course of action.", ids(3, 2), ["Immediate reporting allows employees' missing overtime payments to be identified and corrected.", "The employer must spend time or money correcting payroll promptly but can reduce continuing payment disputes.", "Concealment can leave employees receiving less pay than they earned.", "The employer may face growing complaints and loss of staff trust when the known error is discovered."], "Cover both stakeholders under both actions; do not award four marks for repeating that money is lost."),
    e(2, 3, "A library wants to prevent overdue loans by publishing borrowers' names and reading histories. Private reminders would also reach overdue borrowers. Justify a course of action and explain one safeguard and one limitation of your proposal.", ids(3, 3), ["Use private reminders because they address late returns without exposing reading histories to the public.", "Keep reminder records accessible only to authorised library staff, reducing inappropriate disclosure.", "A wrong address may still send a reminder to the wrong person, so contact details and delivery errors need review."], "A valid alternative conclusion needs evidence that addresses the privacy harm and the stated purpose."),
  ],
  summary: [["Stakeholders", "Name the people affected and explain their connection to the decision."], ["Consequences", "Trace each action to a benefit, harm or responsibility; compare ethical and unethical courses."], ["Alternatives", "Check whether a less intrusive action can achieve the purpose."], ["Judgement", "Choose a justified response with safeguards and acknowledge relevant limitations."]],
};

const softwareLicences = {
  subtitle: "Explain copyright protection, distinguish software licensing approaches and choose a licence from stated permissions and requirements.",
  guidingQuestion: "Which rights does a user need, and which licence actually grants them?",
  diagnostic: { prompt: "A program is available to download without payment. Does that establish permission to change and redistribute its source?", answer: "No. Price does not establish those permissions; inspect the licence terms and source availability." },
  objectives: [objective(4, 1, "Explain why copyright legislation is needed for software."), objective(5, 1, "Explain free software in the Free Software Foundation approach."), objective(5, 2, "Explain the role of the Open Source Initiative and open-source permissions."), objective(5, 3, "Describe shareware and its trial restrictions."), objective(5, 4, "Explain commercial software licensing and distinguish commercial from proprietary."), objective(5, 5, "Justify a licence choice using a given situation's requirements.")],
  units: [
    unit("COPYRIGHT", "Why software needs copyright protection", ids(4, 1), [
      "Writing software takes time, skill and investment, while copying a finished program can cost very little. Copyright legislation gives the rights holder enforceable control over protected expression such as original source code and documentation. This allows unauthorised copying or distribution to be challenged and enables creators to grant permissions and obtain revenue from their work.",
      "Copyright protects the expression of a program rather than every underlying idea or mathematical method. A licence grants permission for specified acts under conditions; buying a copy normally does not transfer ownership of its copyright. A user should establish the applicable permissions before copying, modifying or redistributing software, taking account of any relevant legal exceptions.",
    ], [table("Separate the right from permission to use it", ["Concept", "Question it answers", "Example"], [["Copyright", "Who controls restricted uses of the expression?", "Rights in original source code"], ["Software licence", "What may this user do and under which conditions?", "Install on ten authorised machines"], ["Copyright transfer", "Has ownership itself changed?", "A separate agreement assigning the rights"]]), worked("A purchased program copied to a class", [["Situation", "A tutor buys software whose licence permits installation on one machine. The tutor wants to copy it to twenty classroom computers."], ["Read the permission", "The payment obtained a one-machine permission; it did not transfer the source code's copyright or grant twenty installations."], ["Decision", "Obtain suitable classroom permissions or select another tool whose licence permits the intended installations."], ["Reason", "Cheap copying does not remove the creator's enforceable rights or enlarge the licence that was purchased."]])],
    "Permission to download one copy is not unrestricted permission to distribute copies to others.",
    "Why can a licence allow copying without ending copyright protection?", "The rights holder can grant particular permissions while retaining ownership and enforcing the licence's conditions."),
    unit("FSF", "Free software and the Free Software Foundation", ids(5, 1), [
      "The Free Software Foundation (FSF) promotes software freedom. Its approach gives users freedoms to run a program for any purpose, study and change it, redistribute copies, and distribute modified versions. Access to source code is necessary for studying how the program works and making useful changes.",
      "Free refers to these freedoms, not necessarily a zero price. A copy or support service can be sold while the user retains the freedoms granted by a free-software licence. Some licences use copyleft conditions to preserve freedoms in distributed derivatives; not every free-software licence imposes the same redistribution conditions.",
    ], [table("Four freedoms in use", ["Freedom", "What a user can do"], [["Run", "Use the program for any purpose"], ["Study and change", "Inspect source and adapt the program"], ["Redistribute", "Share copies with other users"], ["Share modified versions", "Distribute improvements subject to the licence"]])],
    "Free software and free-of-charge software describe different properties.",
    "A developer charges for a copy released under a free-software licence. Is charging alone a contradiction?", "No. The relevant question is whether the licence preserves the user's freedoms, not whether a payment is collected."),
    unit("OSI", "Open source and the Open Source Initiative", ids(5, 2), [
      "The Open Source Initiative (OSI) maintains the Open Source Definition and approves licences that satisfy its criteria. Open-source licensing includes access to source code and permission to modify and redistribute the software. Merely allowing users to look at source code is insufficient if the licence prohibits the necessary uses or redistribution.",
      "FSF and OSI are organisations, not two individual licences. Many licences satisfy both free-software and open-source criteria. Their emphasis differs: the FSF stresses users' freedoms, while the OSI evaluates licences against open-source criteria. For a real choice, read the licence's obligations, such as keeping notices or conditions on distributing modified work.",
    ], [table("Check rights as well as source access", ["Terms offered", "Interpretation"], [["View source, but never modify or redistribute", "Source-visible terms alone do not establish open source"], ["Use, modify and share source under an approved licence", "Open-source permissions with continuing obligations"], ["Sell copies while preserving licence terms", "Charging does not itself prevent open-source distribution"]])],
    "An open-source licence does not mean the software has no owner or no conditions.",
    "A supplier publishes source but bans all redistribution. Is source visibility enough to call its licence open source?", "No. Open-source criteria also require redistribution and modification rights; visibility by itself is insufficient."),
    unit("SHAREWARE", "Shareware: evaluate before continued use", ids(5, 3), [
      "Shareware is distributed so users can try software before paying for continued or complete use. A trial may expire after a stated period or restrict features until a licence is purchased. The exact trial terms determine what use and copying are permitted.",
      "This approach can reduce the risk of buying an unsuitable program because a user can test it on their own system. However, a successful trial is not a permanent entitlement, and shareware does not automatically include source code or permission to modify it. Budget for any required payment and check what happens when the trial ends.",
    ], [table("A 30-day evaluation licence", ["Stage", "Permitted action", "Decision to make"], [["Days 1 to 30", "Test the supplied features", "Does it meet the user's needs?"], ["After day 30", "Continue only under the stated paid terms", "Purchase suitable rights or stop using it"], ["Source modification", "Only if separately permitted", "Do not infer this right from trial access"]])],
    "Shareware is not necessarily permanently free and should not be confused with free software.",
    "Why is a time-limited trial unsuitable as the sole basis for a year-long deployment?", "The organisation needs permission covering the whole deployment, including continued use after the trial expires."),
    unit("COMMERCIAL", "Commercial and proprietary software", ids(5, 4), [
      "Commercial software is developed or supplied as a business activity. A supplier may earn income from licences, subscriptions, support or other services. Commercial and proprietary are not synonyms: a business can sell free or open-source software, while proprietary software can sometimes be offered without payment.",
      "A proprietary licence commonly permits specified use while limiting copying, modification or redistribution. Terms may specify the number of users or devices, duration and support arrangements. Paid support can be useful when it is actually included in the agreement; payment alone does not guarantee support, source access or unrestricted installation.",
    ], [table("Price, business model and permissions", ["Example offer", "Commercial?", "Key licence question"], [["Subscription to a closed-source editor", "Yes", "Which users, devices and term are covered?"], ["Business sells an open-source package", "Yes", "Which permissions and notices apply?"], ["No-charge closed-source utility", "Price alone does not establish the business model", "Are changes or redistribution allowed?"]])],
    "Do not infer proprietary restrictions solely from the word commercial; examine the actual licence.",
    "A company sells open-source software with an optional support contract. Can it still be commercial software?", "Yes. Commercial concerns business activity, while open source concerns the rights granted by the licence."),
    unit("LICENCE-CHOICE", "Choose a licence from the requirements", ids(5, 5), [
      "Identify the organisation's required acts before selecting software: running it on the intended devices, modifying source, distributing copies or obtaining support. Then compare those needs with the permissions, costs and obligations of the offered licences. A cheap option is unsuitable if its terms prohibit a required act.",
      "A justification connects a stated requirement to a licence feature and its consequence. Check practical limits as well: source modification needs skilled staff, a trial needs a continuation plan, and supplier support needs agreed scope and availability. There is no single licence category that is best for every organisation.",
    ], [table("Match a requirement to a licence feature", ["Required activity", "Evidence to seek"], [["Adapt source and share the adaptation", "Modification and redistribution permissions plus applicable conditions"], ["Evaluate an unfamiliar tool", "Trial duration and available features"], ["Deploy to a fixed team", "Enough authorised seats and an appropriate term"], ["Obtain help for critical work", "A support agreement covering the required service"]]), worked("Choose a tool for community centres", [["Requirements", "A charity has programmers, needs to translate a tool and distribute the translated version to ten centres, and has no budget for licence fees."], ["Offers", "A: no-charge open-source software allowing modification and redistribution if notices are preserved. B: a free 14-day trial with no source access. C: a paid, one-centre proprietary licence forbidding redistribution."], ["Choice", "Choose A: its permissions cover translation and distribution, and the licence price fits the budget."], ["Obligation and limit", "Preserve the required notices in distributed copies and allocate staff time for maintenance; no-charge licensing does not eliminate development costs."]])],
    "A licence choice needs the supplied scenario and terms, not a claim that one category is always cheapest or safest.",
    "If a school only needs unmodified software with guaranteed response times, must it choose open source?", "No. Compare the actual installation rights, cost and support agreement; source modification may not be a requirement."),
  ],
  practice: [
    q(3, 1, "Explain two reasons why copyright legislation is needed for software that takes a year to develop but can be copied in seconds.", ids(4, 1), ["Enforceable rights allow the creator to challenge unauthorised copies despite the low cost of making them.", "Control over permitted distribution gives the creator a way to obtain revenue to support the development investment."], "Develop the connection between copying, ownership and investment."),
    q(3, 2, "Describe the four freedoms associated with the FSF's free-software approach and state which need source access.", ids(5, 1), ["Users may run the software for any purpose.", "Users may study and change how it works; this requires source code.", "Users may redistribute copies.", "Users may distribute modified versions; producing meaningful source modifications requires source access."], "Freedom concerns permitted actions, not a promise that every copy costs nothing."),
    q(3, 3, "Explain the role of the OSI and why publishing readable source while prohibiting all modifications does not establish open-source licensing.", ids(5, 2), ["The OSI assesses licences against its Open Source Definition and approves those meeting the criteria.", "A licence prohibiting all modifications withholds a required open-source permission even if the source can be read."], "Distinguish a licence's permissions from the visibility of a file."),
    q(3, 4, "A shareware editor stops saving documents after a 21-day trial unless a licence is bought. Explain one benefit of the trial and one action needed for continued full use.", ids(5, 3), ["The user can test whether the editor suits their work before committing to a purchase.", "The user must obtain the stated paid permission to keep the full saving functionality after the trial."], "Do not describe this time-limited offer as permanently free software."),
    q(3, 5, "A company sells an open-source program, while another gives away a closed-source utility. Explain why price alone does not distinguish open-source and proprietary licensing.", ids(5, 2, 4), ["The sold program may retain modification and redistribution permissions, so a price does not remove its open-source status.", "The no-charge utility may still restrict changes and copying, so zero price does not grant open-source rights."], "Compare permissions, not just payment."),
    q(3, 6, "A proprietary licence covers five named users for one year, with support only during office hours. State three terms a manager should check before assigning it to eight users who need round-the-clock help for two years.", ids(5, 4), ["Increase or change the permission to cover all eight users.", "Obtain a term or renewal arrangement covering two years.", "Arrange support availability that covers the required hours."], "Use the stated licence constraints; do not assume payment covers every deployment."),
    q(3, 7, "A volunteer group must modify a program and share it with partner groups. Offer A permits both acts if copyright notices are retained. Offer B permits use only and supplies no source. Justify one choice and state an obligation.", ids(5, 5), ["Choose A because its modification rights allow the group's required changes.", "Its redistribution rights allow partner groups to receive the adapted copies.", "Keep the specified copyright notices when distributing the software."], "A valid justification uses the offered terms rather than a category label alone."),
    q(3, 8, "A shop is unsure whether a stock-control program works with its scanner. Its shareware trial includes scanner support for 30 days, and the shop can pay for continued use. Justify using the trial before purchase and explain one limitation.", ids(5, 3, 5), ["Testing the supplied scanner support can establish compatibility before the shop pays.", "The trial only authorises the stated period, so a successful test still needs a licence purchase for later operation."], "The scenario makes evaluation useful but does not establish indefinite free use."),
  ],
  authoredExamQuestions: [
    e(3, 1, "An independent developer spends months creating a simulation. A training firm copies it to its customers without permission, arguing that electronic copies cost almost nothing. Explain why copyright legislation is needed here and why buying one copy would not normally settle the firm's distribution rights.", ids(4, 1), ["The low copying cost enables others to distribute the developer's expression without funding the work that produced it.", "Copyright supplies a legal basis for controlling and challenging that unauthorised distribution.", "Control of licensed distribution can help the developer receive a return on the simulation's creation.", "Purchasing a copy generally grants specified use rather than ownership or unrestricted rights to distribute customer copies."], "Do not claim copyright gives ownership of every scientific idea used by the simulation."),
    e(3, 2, "Describe how FSF and OSI relate to software licensing. A supplier calls a 10-day, closed-source trial 'free software because it is commercial shareware supplied at zero price'. Explain two errors in that reasoning.", [...ids(5, 1, 2, 3, 4)], ["The FSF promotes licences that preserve users' freedoms to run, study, change and share programs.", "The OSI maintains open-source criteria and recognises licences that comply with them.", "A temporary zero-price offer does not establish the freedoms associated with free software, particularly when source access and change rights are absent.", "Commercial describes business activity and shareware describes trial distribution; neither label proves free-software permissions, and continued use may need payment."], "FSF and OSI are organisations; the supplier's licence terms determine what the user may do."),
    e(3, 3, "A clinic needs software for six receptionists for three years. It will not modify source and requires a two-hour support response. Offer A is no-charge open-source software with community help but no response commitment. Offer B is a proprietary subscription covering six users and contracted two-hour support. The clinic can afford B for all three years. Justify a choice, explain one trade-off and state a licence term to confirm.", ids(5, 4, 5), ["B meets the clinic's stated support response requirement through a contract, unlike the uncommitted community help in A.", "Its six-user permission matches the reception team and the given budget supports the planned subscription period.", "The clinic accepts subscription expenditure and source restrictions in exchange for a service it needs; modification rights are not required here.", "Confirm that the subscription and support coverage remain valid throughout all three years and cover the intended use."], "Choosing open source solely because it is free to obtain does not address the required support commitment."),
  ],
  summary: [["Copyright and permission", "Rights in software expression remain distinct from the acts a particular licence permits."], ["FSF and OSI", "User freedoms and open-source criteria overlap across many licences; source visibility alone is insufficient."], ["Shareware", "Evaluate under stated trial terms, then obtain the rights needed for continued use."], ["Commercial", "Business activity can use open-source or proprietary licences; price alone does not determine permissions."], ["Selection", "Match required use, changes, distribution and support to actual terms and obligations."]],
};

const artificialIntelligence = {
  subtitle: "Explain what AI does, connect applications to their decisions and evaluate social, economic and environmental consequences in context.",
  guidingQuestion: "How does an AI system's particular decision create benefits, risks and costs?",
  diagnostic: { prompt: "A warehouse replaces paper forms with an electronic list. Does that change alone establish that it uses AI?", answer: "No. Storing information electronically does not by itself demonstrate an AI task such as recognition, inference or prediction." },
  objectives: [objective(6, 1, "Explain artificial intelligence and distinguish it from simply storing or processing data."), objective(6, 2, "Describe AI applications by linking input, task, output and use."), objective(6, 3, "Explain social benefits and risks of AI applications."), objective(6, 4, "Explain economic benefits and costs of AI applications."), objective(6, 5, "Explain environmental benefits and costs of AI applications."), objective(6, 6, "Evaluate an AI application using relevant impacts, safeguards and a supported conclusion.")],
  units: [
    unit("AI-MEANING", "What artificial intelligence does", ids(6, 1), [
      "Artificial intelligence (AI) enables computer systems to perform tasks associated with human intelligence, such as interpreting language, recognising patterns, reasoning or making predictions and decisions. A system may use expert-written rules or a model learned from data to infer an output for a new input.",
      "An AI system does not have to be a physical robot, conscious or human-like in every respect. A recommendation service can use AI entirely in software. Conversely, recording information or performing a fixed arithmetic calculation does not by itself demonstrate AI. Identify the interpretation, inference or decision task being performed.",
    ], [table("Identify the task", ["System behaviour", "Interpretation"], [["Store a typed delivery address", "Data storage alone"], ["Add stated prices on an invoice", "Ordinary arithmetic alone"], ["Recognise a handwritten address", "AI pattern-recognition application"], ["Recommend a product from preference patterns", "AI recommendation application"]])],
    "AI is not synonymous with every automated system, and it does not guarantee human understanding.",
    "Can a recommendation website use AI without a robot?", "Yes. A software model can infer suitable recommendations from patterns in data without controlling a physical machine."),
    unit("AI-APPLICATIONS", "From input to an AI-assisted action", ids(6, 2), [
      "Describe an application as a connected chain. State the input information, what the AI infers or recognises, the resulting output and how that output is used. 'AI is used in medicine' names an area but does not explain an application; interpreting a scan to flag a possible abnormality gives a task and a use.",
      "Outputs can guide a person or control an action. A fraud-detection model may flag a payment for an investigator, while an autonomous controller may select an action from sensor readings. Confidence, reliability and consequences determine how much checking or human intervention is appropriate. A prediction can be useful without being certain.",
    ], [table("Concrete AI applications", ["Input", "AI task", "Output and use"], [["Medical images", "Classify suspicious patterns", "Flag an area for clinical review"], ["Past transactions and a new payment", "Detect unusual payment patterns", "Risk flag for fraud investigation"], ["Recorded speech", "Recognise words", "Text for captions or voice input"], ["Equipment vibration and temperature", "Predict a developing fault", "Maintenance alert"], ["User preferences and item features", "Rank likely interests", "Recommended items"], ["Road-camera and other sensor readings", "Interpret obstacles and routes", "Control decisions in an autonomous vehicle"]]), worked("A pump maintenance alert", [["Input", "A factory records vibration and temperature from a water pump and has examples of earlier faults."], ["Inference", "The model recognises a pattern associated with bearing wear and estimates an increased chance of failure."], ["Use", "A technician inspects the bearing and schedules a repair before an unexpected shutdown."], ["Limit", "A false alert could prompt unnecessary work, while a missed fault could still cause a breakdown; the prediction needs validation and monitoring."]])],
    "A list of sectors is not a description of what an AI system does in those sectors.",
    "In speech-to-text, what is the input and what does the AI output?", "Audio speech is the input; recognised words represented as text are the output."),
    unit("AI-SOCIAL", "Social effects: access, fairness and privacy", ids(6, 3), [
      "Social impacts concern how people live, participate and are treated. Speech recognition can improve access for someone unable to type, and translation can help people communicate. The benefit depends on whether the system works adequately for its users, including different accents, languages or disabilities.",
      "Biased or unrepresentative data can contribute to unequal error rates and unfair decisions. Collecting personal information also creates privacy risks. Explain who benefits or is harmed: a hiring system that rejects qualified applicants unfairly changes their opportunities. Testing across affected groups, limiting unnecessary collection and providing human review or appeal can reduce specific risks.",
    ], [table("One application, different social effects", ["AI service", "Possible benefit", "Possible concern", "Relevant safeguard"], [["Automatic captions", "Access to spoken material", "Errors for some speakers", "Correction and user feedback"], ["Job shortlisting", "Faster handling of applications", "Qualified groups unfairly rejected", "Fairness testing and an appeal route"], ["Personal recommendations", "Find relevant information", "Detailed personal profiling", "Limit collection and retention"]])],
    "Consistent automated processing can consistently repeat a bias; consistency is not proof of fairness.",
    "Why might an average accuracy figure hide an accessibility problem?", "Good performance for a large group can conceal much worse performance for a smaller group with different speech or access needs."),
    unit("AI-ECONOMIC", "Economic effects: productivity, work and cost", ids(6, 4), [
      "Economic impacts concern resources, production, costs and employment. An AI tool may process routine cases more quickly, reduce waste or predict failures before expensive disruption. Link the saving to the activity: an early equipment warning may allow planned maintenance during a quiet period rather than an emergency shutdown.",
      "Costs include developing or buying the system, obtaining and maintaining suitable data, operating hardware and training staff. Incorrect decisions can create rework or losses. Automation may reduce demand for some tasks while creating or changing roles in supervision, maintenance and specialist support; workers may need retraining. A productivity gain does not mean every worker or business benefits equally.",
    ], [table("Account for more than one cost", ["Change", "Possible economic consequence"], [["Process routine documents faster", "Greater output per staff hour"], ["Predict component wear", "Fewer disruptive emergency repairs"], ["Introduce a new model", "Development, integration and training expenditure"], ["Automate an existing task", "Job displacement, redesign or retraining"], ["Accept incorrect output", "Correction costs or financial losses"]])],
    "AI does not necessarily remove all jobs or eliminate operating costs.",
    "Why is fewer manual checks not enough to prove a net saving?", "Compare the labour saving with purchase, operation, oversight, retraining and error costs for the actual deployment."),
    unit("AI-ENVIRONMENT", "Environmental costs and potential savings", ids(6, 5), [
      "Training and operating AI models uses computing equipment and electricity, and cooling may require water or additional energy. Manufacturing and replacing hardware also uses materials and produces waste. Emissions depend partly on the energy supply, so identical computation can have different environmental consequences in different settings.",
      "An AI application can also reduce resource use: optimising delivery routes may reduce fuel consumption, adjusting heating to occupancy may reduce energy waste, and detecting faults may prolong equipment life. Compare these savings with the system's own operation and hardware lifecycle. The result depends on the scale of use and the alternative being replaced, not on an assumption that all AI is environmentally beneficial or harmful.",
    ], [table("Compare both sides of AI-controlled heating", ["System footprint", "Potential saving", "Evidence needed"], [["Electricity for model operation", "Less heating in unused rooms", "Total energy before and after"], ["Sensors and computing hardware", "Better use of existing equipment", "Manufacture, lifespan and replacement needs"], ["Cooling and data services", "Avoid unnecessary operation", "Savings relative to a simpler controller"]])],
    "Lower energy use in the controlled device is not the whole environmental balance if the AI service itself consumes resources.",
    "What comparison would help assess an AI route planner's environmental benefit?", "Compare reduced vehicle fuel use with the planner's computing and hardware footprint, using the previous routing method as the baseline."),
    unit("AI-EVALUATION", "Evaluate an application in its setting", ids(6, 6), [
      "Start an evaluation by identifying the AI task and the decision it influences. Develop relevant benefits and drawbacks through effects on named stakeholders or resources. Consider social, economic and environmental dimensions where they apply to the question, but do not force an unrelated point into a response simply to repeat three labels.",
      "Reach a supported judgement using the supplied constraints. State a suitable safeguard or alternative and explain the risk it addresses. Human oversight needs a workable review process and competent reviewers; writing 'a human checks it' does not establish that errors will be caught. A conditional recommendation should say which evidence or conditions would make deployment acceptable.",
    ], [flow("Evaluate a proposed deployment", [["Application", "Identify the input, inference and decision affected."], ["Impacts", "Develop benefits and risks using the relevant setting."], ["Control", "Match safeguards or alternatives to the specific risks."], ["Judgement", "Recommend a course with reasons, conditions and remaining limits."]]), worked("A hospital tests scan prioritisation", [["Proposal", "An AI service flags scans that may need urgent review. Clinicians retain responsibility for interpreting scans, and the hospital is comparing it with its existing queue."], ["Benefits", "Faster flagging may shorten waits for urgent cases and let specialists direct their time to patients needing rapid attention."], ["Costs and risks", "Missed cases could delay care, different patient groups may experience different error rates, and the service adds operating and equipment costs."], ["Safeguards", "Evaluate sensitivity across patient groups, retain a route for reviewing unflagged scans and allow clinicians to override the queue priority."], ["Judgement", "Use a monitored pilot if it improves waiting times without unacceptable missed cases. Compare its resource costs with the existing process before expanding it."]])],
    "A general claim that AI is fast, accurate or objective is not a context-based evaluation.",
    "What makes 'Use AI if it is safe' an incomplete conclusion?", "It does not specify how safety will be assessed, what safeguards are needed or how the decision follows from the scenario's evidence."),
  ],
  practice: [
    q(4, 1, "Explain what is meant by artificial intelligence and distinguish recognising a handwritten postcode from storing a postcode typed by a user.", ids(6, 1), ["AI performs tasks associated with human intelligence, such as interpreting patterns or making inferences.", "Handwriting recognition interprets an image to infer characters, while storing an already typed postcode alone does not demonstrate that task."], "Do not define AI as all uses of computers or only as robots."),
    q(4, 2, "Describe an AI speech-to-text application using its input, recognition task, output and practical use.", ids(6, 2), ["Recorded or live speech supplies audio input.", "The system recognises speech patterns and infers the spoken words.", "It produces text that can be used for captions or dictation."], "Connect the stages instead of listing unrelated AI application areas."),
    q(4, 3, "An AI payment service flags unusual transactions for staff review. Describe what the model analyses and how its output is used; explain why a flag is not proof of fraud.", ids(6, 2), ["The model examines features of a new payment in relation to transaction patterns.", "A risk flag directs staff attention to a payment needing investigation.", "A legitimate unusual payment can also be flagged, so further evidence is needed."], "A prediction or classification may be wrong."),
    q(4, 4, "Automatic captions work well for one accent but often misrecognise another. Explain one social benefit and one social risk of using them in an online lesson, and suggest a safeguard.", ids(6, 3), ["Captions can give students who cannot hear the audio access to the spoken lesson.", "Students relying on poorly recognised speech may receive inaccurate information and unequal access.", "Provide a way to correct captions or supply checked lesson text for affected users."], "Name the students affected and connect the safeguard to caption errors."),
    q(4, 5, "A factory uses AI to predict machine faults. Explain one economic benefit, one system cost and one possible effect on workers.", ids(6, 4), ["Earlier repair scheduling can reduce production time lost to unexpected breakdowns.", "Sensors, model operation and integration require expenditure even when forecasts are useful.", "Maintenance staff may need retraining to interpret alerts and plan work differently."], "Do not treat a reduction in emergency repairs as elimination of all maintenance jobs."),
    q(4, 6, "An AI system reduces a building's heating demand but requires new servers. Explain one environmental benefit and two environmental costs that should be considered.", ids(6, 5), ["Lower heating demand can reduce fuel or electricity consumption in the building.", "Running and cooling the servers consumes energy and may add emissions.", "Making and eventually replacing the servers uses materials and creates disposal impacts."], "Include the AI equipment's footprint as well as the controlled building's saving."),
    q(4, 7, "A recruitment firm wants AI to reject applicants automatically. Testing shows good overall accuracy but much poorer results for one group. Evaluate automatic rejection and recommend a safeguard.", ids(6, 3, 6), ["Automated screening can process applications quickly, reducing routine staff workload.", "The poorer group performance can unfairly exclude suitable applicants, so the overall average is insufficient evidence of fairness.", "Use audited assistance with human review and an appeal route rather than final rejection solely from the model.", "Deployment should depend on investigating the unequal errors and showing that review can address them."], "A judgement must use the supplied group-performance evidence."),
    q(4, 8, "A delivery company claims its AI route planner is environmentally beneficial because its computers are efficient. Explain why this evidence alone is insufficient and suggest a more useful comparison.", ids(6, 5, 6), ["Efficient computers still consume resources and do not establish that the resulting vehicle routes save fuel.", "Compare total vehicle fuel use and the planning system's energy and hardware impacts with those of the previous routing approach."], "State a baseline and evaluate the whole application rather than one component."),
  ],
  authoredExamQuestions: [
    e(4, 1, "A recycling centre uses camera images to recognise material types and direct items to different bins. Explain why the recognition is an AI application, describe the input-to-action chain and explain one consequence of an incorrect classification.", ids(6, 1, 2), ["The system interprets visual patterns to infer a material category, a task associated with intelligent recognition.", "A camera supplies images of items on the sorting belt.", "A model assigns a category and the controller directs the item towards its corresponding bin.", "A mistaken category may contaminate a recyclable-material stream or send a reusable item to disposal."], "Describe recognition rather than claiming that moving an item alone proves AI is present."),
    e(4, 2, "A council proposes AI to prioritise requests for housing repairs. It expects faster processing and lower administration costs, but tests show that requests written in less common languages are often assigned low priority incorrectly. Evaluate the proposal, including a social effect, an economic effect, a safeguard and a justified conclusion.", ids(6, 3, 4, 6), ["Faster triage could shorten delays before urgent repairs reach the appropriate team.", "The language-related errors could leave some residents waiting longer for equally serious faults, creating unequal treatment.", "Less routine administration may save staff time, although translation, integration and oversight still have costs.", "Arrange multilingual review and an accessible challenge route for low-priority decisions to address the observed error pattern.", "Use the system only as monitored assistance after checking that the review process corrects these errors; the given tests do not justify unreviewed prioritisation."], "Credit a different supported judgement if it addresses the unequal errors, costs and available controls."),
    e(4, 3, "A farm is considering AI irrigation. Sensors feed a model that predicts when crops need water. Explain two potential environmental benefits and two environmental costs, then state what evidence is needed before claiming a net environmental improvement.", ids(6, 5, 6), ["More targeted watering may reduce extraction of scarce water compared with the existing schedule.", "Avoiding unnecessary pumping may lower the energy used to irrigate the fields.", "Model operation and data transmission require electricity throughout the season.", "Manufacturing and replacing sensors and computing devices consumes resources and adds waste.", "Compare measured water and energy savings with the system's operating and hardware impacts over its life against the existing irrigation method."], "The ability to predict watering needs does not by itself prove a net resource saving."),
  ],
  summary: [["Meaning and application", "Identify the interpretation or inference task, then connect input, output and the decision affected."], ["Social", "Consider access, privacy and fair treatment for the actual users."], ["Economic", "Weigh productivity and avoided losses against costs and changes to work."], ["Environmental", "Compare application savings with computation and hardware over their lifecycle."], ["Evaluation", "Use scenario evidence to justify a decision with specific safeguards and limits."]],
};

const authoredLessons = { 35: professionalEthics, 36: ethicalDecisions, 37: softwareLicences, 38: artificialIntelligence };

export function authorSection7Lesson(source) {
  if (source.section === 7) {
    const authored = structuredClone(authoredLessons[source.originalLesson]);
    if (!authored) throw new Error(`Missing S7 lesson ${source.originalLesson}`);
    return {
      ...source, ...authored, units: authored.units.map(addSection7Visual), summaryMode: "authored",
      teachingCheckpoints: ["Answer each knowledge-unit check before revealing its explanation.", "Use the worked scenario to connect a claim to evidence, then attempt the practice and independent exam questions."],
      sources: [
        "Cambridge 9618 2027–2029 syllabus 7.1: https://www.cambridgeinternational.org/Images/721397-2027-2029-syllabus.pdf",
        ...(source.originalLesson === 35 ? ["BCS Code of Conduct: https://www.bcs.org/membership-and-registrations/become-a-member/bcs-code-of-conduct/"] : []),
        ...(source.originalLesson === 37 ? ["FSF software freedoms: https://www.gnu.org/philosophy/free-sw.en.html", "GNU software categories: https://www.gnu.org/philosophy/categories.en.html", "OSI Open Source Definition: https://opensource.org/osd", "WIPO copyright overview: https://www.wipo.int/en/web/copyright/faq-copyright"] : []),
        "Original teaching scenarios, practice questions and marking points.",
      ],
    };
  }
  if (source.kind !== "review" || source.paper !== 1) return source;
  const objectiveIds = source.objectives.filter(([id]) => id.startsWith("S7.")).map(([id]) => id);
  const reviewUnit = unit("REVIEW", "Section 7: Ethics and ownership", objectiveIds, [
    "Explain why specialists owe duties to affected people, then use the actual decision to identify stakeholders and compare the consequences of ethical and unethical actions. Professional membership supplies standards and development; it leaves the individual responsible for applying them.",
    "For software ownership, distinguish copyright from the permissions in a licence. Compare free-software freedoms, open-source criteria, trial limits and commercial terms against the required use. For AI, describe the task performed before assessing its effects on people, costs and resources.",
  ], [table("Retrieve the complete S7 reasoning", ["Focus", "Explain or apply"], [["Professional ethics", "Why do users depend on responsible specialists?"], ["BCS and IEEE", "How does membership support practice?"], ["Ethical decisions", "Who is affected by each available action?"], ["Copyright", "Why protect software expression?"], ["Licences", "Which permissions meet the stated requirements?"], ["AI", "What decision does the system make and what follows from it?"]])],
  "A keyword or category label must be connected to the decision the question asks about.",
  "A supplier's AI product is sold commercially. Does that establish either that its licence is proprietary or that its decisions are fair?", "Neither follows. Read the licence permissions separately from evaluating the model's performance and effects.");
  const practice = [
    question("REV-P1-S7-Q1", "A systems analyst hides a known emergency-contact error to avoid delaying a client demonstration. Explain why this conflicts with professional ethics, give a consequence of reporting it, and explain how professional-body membership could help the analyst respond.", ["S7.01.R", "S7.02.R", "S7.03.R"], ["Concealing a known fault prevents the client from judging whether emergency contacts can be relied upon.", "Reporting allows correction before an emergency, although the demonstration may be postponed.", "Guidance from a professional code or experienced members can support an honest escalation of the concern."], "Use the supplied fault and both professional responsibility and practical support."),
    question("REV-P1-S7-Q2", "A student claims, 'Copyright ends when source is published, and shareware can always be used forever without paying.' Explain the two errors and state why a paid open-source product can still be commercial software.", ["S7.04.R", "S7.05.R"], ["Publication does not itself surrender rights in source code; permissions depend on the licence.", "A shareware offer can limit trial time or features and require a purchase for continued full use.", "Selling software is business activity even if the licence retains open-source freedoms."], "Keep ownership, price, trial terms and modification rights separate."),
    question("REV-P1-S7-Q3", "An archive needs to adapt an indexer and distribute it to partner archives. Licence A supplies source and permits both acts if notices remain. Licence B permits one unmodified installation. Justify a choice and state a continuing responsibility.", ["S7.05.R"], ["A authorises the adaptation needed for the archive's index format.", "A permits distribution to partners whereas B's single-installation condition does not cover that plan.", "The archive must retain the specified notices in its distributed versions."], "Use the permissions in the question rather than guessing from the licence name."),
    question("REV-P1-S7-Q4", "A transport service uses AI to recognise spoken destinations. Describe this application and explain one social benefit, one economic cost and one environmental cost.", ["S7.06.R"], ["The system interprets passengers' audio to produce recognised destination information for journey planning.", "Voice input may help passengers who cannot conveniently use a keyboard or touch screen.", "The service must fund development or purchase, integration and continued support of recognition.", "Processing speech and operating the supporting equipment consumes electricity and hardware resources."], "Distinguish the AI task from its consequences in each requested dimension."),
  ];
  return {
    ...source,
    units: source.units.map((u) => u.heading === "Section 7: Ethics and ownership" ? reviewUnit : u),
    practice: [...source.practice, ...practice],
  };
}
